UPDATE /* com.seinfo.protoA.component.admin.mapper.AdminMapper.updateProposalState */
       seinfo_proposal
   SET state_lrtp = #{stateLrtp}

           , state_rtp = #{stateRtp}


           , chief_manager = #{chiefManager}
           , chief_manager_d = now()

     , mod_user_id = #{userEmail}
     , mod_dt = now()
 WHERE proposal_no = #{proposalNo}

mapper.insert:
INSERT /* com.seinfo.protoA.component.admin.mapper.AdminMapper.insertRequestCont */
    INTO seinfo_request_cont
        (
          proposal_no
        , request_yn
        , answer_yn
        , request_seq
        , draw_title
        , draw_contents
        , request_due_d
        , reg_dt
        , reg_user_id
        )
    VALUES
        (
           #{proposalNo}
        ,  #{requestYn}
        ,  #{answerYn}
        ,  (SELECT ifnull(MAX(x.request_seq), 0) +1
               FROM seinfo_request_cont x
               WHERE x.proposal_no = #{proposalNo}
                 AND x.request_yn = 'M')
        ,  #{drawTitle}
        ,  #{drawContents}
        ,  now()
        ,  now()
        ,  #{userEmail}
        )

mapper.update:
UPDATE /* com.seinfo.protoA.component.admin.mapper.AdminMapper.updateProposalState */
       seinfo_proposal
   SET  mod_user_id = #{userEmail}
      , mod_dt = now()

          , assess_skip_yn = #{assessSkipYn}
          , assess_skip_res = #{assessSkipRes}
          , state_rtp = '90'
          , state_lrtp = '90'


          , last_result_yn = 'Y'
          , last_result = #{lastResult}
          , last_result_cont = #{lastResultCont}
          , last_result_d = now()
          , state_rtp = '99'
          , state_lrtp = '99'

  WHERE proposal_no = #{proposalNo}
